import sqlite3from pathlib import Pathfrom fastapi import APIRouter, HTTPExceptionrouter = APIRouter()BASE_DIR = Path(__file__).resolve().parents[3]DB_PATH = BASE_DIR / "data" / "nifty100.db"@router.get("/market-cap/{ticker}")def get_market_cap_history(ticker: str):    """Retrieve market cap history."""    conn = sqlite3.connect(DB_PATH)    conn.row_factory = sqlite3.Row    query = """        SELECT            year,            period,            pe_ratio,            pb_ratio,            ev_ebitda,            dividend_yield_pct        FROM market_cap        WHERE UPPER(company_id) = UPPER(?)          AND year BETWEEN 2019 AND 2024        ORDER BY year    """    rows = conn.execute(query, (ticker,)).fetchall()    conn.close()    if not rows:        raise HTTPException(            status_code=404,            detail="Market-cap data not found",        )    return [dict(row) for row in rows]